"use strict";(globalThis.webpackChunkmy_site=globalThis.webpackChunkmy_site||[]).push([[4645],{2877:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/physical-ai-book/docs/intro","label":"Introduction to Physical AI & Humanoid Robotics","docId":"intro","unlisted":false},{"type":"category","label":"Module 1: The Robotic Nervous System (ROS 2)","items":[{"type":"link","href":"/physical-ai-book/docs/module-1-ros2/introduction-to-ros2","label":"Introduction to ROS 2","docId":"module-1-ros2/introduction-to-ros2","unlisted":false},{"type":"link","href":"/physical-ai-book/docs/module-1-ros2/ros2-actions-and-services","label":"ROS 2 Services and Actions","docId":"module-1-ros2/ros2-actions-and-services","unlisted":false},{"type":"link","href":"/physical-ai-book/docs/module-1-ros2/ros2-tf2-transforms","label":"ROS 2 TF2: Coordinate Frames and Transforms","docId":"module-1-ros2/ros2-tf2-transforms","unlisted":false},{"type":"link","href":"/physical-ai-book/docs/module-1-ros2/ros2-navigation-basics","label":"ROS 2 Navigation Basics (Nav2)","docId":"module-1-ros2/ros2-navigation-basics","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/physical-ai-book/docs/module-1-ros2/introduction-to-ros2"},{"type":"category","label":"Module 2: The Digital Twin (Gazebo & Unity)","items":[{"type":"link","href":"/physical-ai-book/docs/module-2-digital-twin/intro-to-simulation","label":"Introduction to Simulation and Digital Twins","docId":"module-2-digital-twin/intro-to-simulation","unlisted":false},{"type":"link","href":"/physical-ai-book/docs/module-2-digital-twin/robot-model-creation","label":"Robot Model Creation: URDF/SDF","docId":"module-2-digital-twin/robot-model-creation","unlisted":false},{"type":"link","href":"/physical-ai-book/docs/module-2-digital-twin/unity-simulation-integration","label":"Unity Simulation Integration","docId":"module-2-digital-twin/unity-simulation-integration","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/physical-ai-book/docs/module-2-digital-twin/intro-to-simulation"},{"type":"category","label":"Module 3: The AI-Robot Brain (NVIDIA Isaac)","items":[{"type":"link","href":"/physical-ai-book/docs/module-3-ai-robot-brain/intro-to-isaac-sim","label":"Introduction to NVIDIA Isaac Sim","docId":"module-3-ai-robot-brain/intro-to-isaac-sim","unlisted":false},{"type":"link","href":"/physical-ai-book/docs/module-3-ai-robot-brain/reinforcement-learning-with-isaac","label":"Reinforcement Learning with Isaac Sim","docId":"module-3-ai-robot-brain/reinforcement-learning-with-isaac","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/physical-ai-book/docs/module-3-ai-robot-brain/intro-to-isaac-sim"},{"type":"category","label":"Module 4: Vision-Language-Action (VLA)","items":[{"type":"link","href":"/physical-ai-book/docs/module-4-vla/foundations-of-vla","label":"Foundations of Vision-Language-Action (VLA)","docId":"module-4-vla/foundations-of-vla","unlisted":false},{"type":"link","href":"/physical-ai-book/docs/module-4-vla/prompt-engineering-for-robots","label":"Prompt Engineering for Robots","docId":"module-4-vla/prompt-engineering-for-robots","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/physical-ai-book/docs/module-4-vla/foundations-of-vla"},{"type":"category","label":"Capstone Project: The Autonomous Humanoid","items":[{"type":"link","href":"/physical-ai-book/docs/capstone-project/project-overview","label":"Capstone Project Overview","docId":"capstone-project/project-overview","unlisted":false},{"type":"link","href":"/physical-ai-book/docs/capstone-project/system-integration","label":"System Integration for the Capstone","docId":"capstone-project/system-integration","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/physical-ai-book/docs/capstone-project/project-overview"},{"type":"category","label":"Hardware Requirements & Setup","items":[{"type":"link","href":"/physical-ai-book/docs/hardware-setup/hardware-components","label":"Essential Hardware Components","docId":"hardware-setup/hardware-components","unlisted":false},{"type":"link","href":"/physical-ai-book/docs/hardware-setup/lab-and-cloud-options","label":"Lab Setup vs. Cloud Robotics Options","docId":"hardware-setup/lab-and-cloud-options","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/physical-ai-book/docs/hardware-setup/hardware-components"},{"type":"category","label":"Tutorials","items":[{"type":"link","href":"/physical-ai-book/docs/tutorial-basics/ros2-basic-publisher","label":"ROS 2 Basic Publisher Tutorial","docId":"tutorial-basics/ros2-basic-publisher","unlisted":false}],"collapsed":true,"collapsible":true,"href":"/physical-ai-book/docs/tutorial-basics/ros2-basic-publisher"}]},"docs":{"capstone-project/project-overview":{"id":"capstone-project/project-overview","title":"Capstone Project Overview","description":"This Capstone Project brings together all the concepts and technologies explored throughout \\"Physical AI & Humanoid Robotics.\\" The goal is to design, simulate, and partially implement the control architecture for an Autonomous Humanoid robot capable of performing a complex, real-world task. This project serves as a practical application of ROS 2, Digital Twins, AI-Robot Brains (via NVIDIA Isaac Sim), and Vision-Language-Action (VLA) principles.","sidebar":"tutorialSidebar"},"capstone-project/system-integration":{"id":"capstone-project/system-integration","title":"System Integration for the Capstone","description":"Integrating diverse software and hardware components is a cornerstone of robotics. For our Autonomous Humanoid Capstone Project, this involves weaving together the power of ROS 2 for communication, high-fidelity simulation (Gazebo/Isaac Sim) for the digital twin, and advanced AI frameworks for intelligence. This chapter outlines the architectural considerations and key integration points.","sidebar":"tutorialSidebar"},"hardware-setup/hardware-components":{"id":"hardware-setup/hardware-components","title":"Essential Hardware Components","description":"Building or even understanding a humanoid robot requires familiarity with a diverse set of hardware components. These components form the physical foundation upon which all intelligence and motion are built. This chapter details the critical hardware elements and their roles in a typical humanoid robot.","sidebar":"tutorialSidebar"},"hardware-setup/lab-and-cloud-options":{"id":"hardware-setup/lab-and-cloud-options","title":"Lab Setup vs. Cloud Robotics Options","description":"Developing and operating humanoid robots requires significant computational power, specialized hardware, and often, physical space. Depending on your resources and project scale, you might opt for a traditional local lab setup or leverage the growing capabilities of cloud robotics platforms. This chapter explores the advantages and disadvantages of each.","sidebar":"tutorialSidebar"},"intro":{"id":"intro","title":"Introduction to Physical AI & Humanoid Robotics","description":"Welcome to \\"Physical AI & Humanoid Robotics,\\" your comprehensive guide to the fascinating convergence of artificial intelligence and advanced robotics. This book delves into the principles, technologies, and practical applications that enable intelligent machines to perceive, understand, and interact with the physical world.","sidebar":"tutorialSidebar"},"module-1-ros2/introduction-to-ros2":{"id":"module-1-ros2/introduction-to-ros2","title":"Introduction to ROS 2","description":"Welcome to the foundational module of our journey into humanoid robotics. Just as a biological organism relies on a nervous system to connect its brain to its muscles and sensors, a robot relies on a communication framework to link its computational \\"brain\\" with its physical components. In modern robotics, the de facto standard for this framework is the Robot Operating System (ROS), and we will be focusing on its latest iteration, ROS 2.","sidebar":"tutorialSidebar"},"module-1-ros2/ros2-actions-and-services":{"id":"module-1-ros2/ros2-actions-and-services","title":"ROS 2 Services and Actions","description":"While topics are perfect for continuous data streams (like sensor readings), robotics often requires different communication patterns. Sometimes, you need a direct request-response interaction, or you need to command a long-running task and receive feedback. For these scenarios, ROS 2 provides Services and Actions.","sidebar":"tutorialSidebar"},"module-1-ros2/ros2-navigation-basics":{"id":"module-1-ros2/ros2-navigation-basics","title":"ROS 2 Navigation Basics (Nav2)","description":"One of the most common and complex tasks for a mobile robot is autonomous navigation. This involves perceiving the environment, localizing itself within a map, planning a path to a goal, and executing that path while avoiding obstacles. In ROS 2, the Nav2 stack provides a powerful and flexible framework to achieve this.","sidebar":"tutorialSidebar"},"module-1-ros2/ros2-tf2-transforms":{"id":"module-1-ros2/ros2-tf2-transforms","title":"ROS 2 TF2: Coordinate Frames and Transforms","description":"In robotics, everything moves. Robots move, sensors move, objects in the environment move. To describe where things are in relation to each other, we use coordinate frames and transforms. The TF2 (Transform Frame) library in ROS 2 is the standard way to keep track of these coordinate frames and transform data between them.","sidebar":"tutorialSidebar"},"module-2-digital-twin/intro-to-simulation":{"id":"module-2-digital-twin/intro-to-simulation","title":"Introduction to Simulation and Digital Twins","description":"In robotics, developing and testing on physical hardware is slow, expensive, and often risky. What if you could build, test, and iterate on your robot\'s software in a perfectly simulated virtual world? This is the power of simulation and the concept of a Digital Twin.","sidebar":"tutorialSidebar"},"module-2-digital-twin/robot-model-creation":{"id":"module-2-digital-twin/robot-model-creation","title":"Robot Model Creation: URDF/SDF","description":"Before a robot can be simulated in environments like Gazebo, its physical properties and structure must be digitally defined. This is where Robot Description Formats come into play. The two primary formats used in ROS 2 and Gazebo are URDF (Unified Robot Description Format) and SDF (Simulation Description Format).","sidebar":"tutorialSidebar"},"module-2-digital-twin/unity-simulation-integration":{"id":"module-2-digital-twin/unity-simulation-integration","title":"Unity Simulation Integration","description":"While Gazebo is the workhorse for many ROS-based robotics simulations, Unity offers a powerful alternative, especially when high-fidelity graphics, rich environments, and advanced rendering capabilities are desired. Unity, a popular game engine, has increasingly become a platform for robotics development, particularly with the advent of tools like the Unity Robotics Hub.","sidebar":"tutorialSidebar"},"module-3-ai-robot-brain/intro-to-isaac-sim":{"id":"module-3-ai-robot-brain/intro-to-isaac-sim","title":"Introduction to NVIDIA Isaac Sim","description":"As we delve deeper into building intelligent humanoid robots, the need for powerful simulation environments that can handle complex AI tasks, particularly reinforcement learning, becomes paramount. NVIDIA Isaac Sim emerges as a leading platform designed specifically for this purpose, leveraging NVIDIA\'s expertise in graphics, physics, and AI.","sidebar":"tutorialSidebar"},"module-3-ai-robot-brain/reinforcement-learning-with-isaac":{"id":"module-3-ai-robot-brain/reinforcement-learning-with-isaac","title":"Reinforcement Learning with Isaac Sim","description":"Reinforcement Learning (RL) has emerged as a powerful paradigm for training complex robotic behaviors, allowing robots to learn optimal control policies through trial and error. However, training RL agents on physical robots is often impractical due to safety concerns, wear and tear, and the sheer time required. This is where high-fidelity, GPU-accelerated simulators like NVIDIA Isaac Sim, specifically with its Isaac Gym capabilities, become invaluable.","sidebar":"tutorialSidebar"},"module-4-vla/foundations-of-vla":{"id":"module-4-vla/foundations-of-vla","title":"Foundations of Vision-Language-Action (VLA)","description":"The frontier of AI and robotics is moving towards systems that can understand and interact with the world in a more human-like way. This involves bridging the gap between perception (vision), high-level reasoning (language), and physical execution (action). This is the domain of Vision-Language-Action (VLA) models.","sidebar":"tutorialSidebar"},"module-4-vla/prompt-engineering-for-robots":{"id":"module-4-vla/prompt-engineering-for-robots","title":"Prompt Engineering for Robots","description":"In the era of large language models (LLMs) and vision-language models (VLMs), prompt engineering has emerged as a critical skill. For robots, prompt engineering extends beyond generating text; it involves crafting effective prompts that enable VLMs to interpret complex instructions, reason about the physical world, and generate actionable commands for robotic systems.","sidebar":"tutorialSidebar"},"tutorial-basics/ros2-basic-publisher":{"id":"tutorial-basics/ros2-basic-publisher","title":"ROS 2 Basic Publisher Tutorial","description":"This tutorial will guide you through creating a simple ROS 2 publisher in Python. A publisher node sends messages over a topic, which can then be received by subscriber nodes.","sidebar":"tutorialSidebar"}}}}')}}]);